<?php
namespace App\Controller;
use App\Entity\Offer; use Doctrine\ORM\EntityManagerInterface; use Symfony\Bundle\FrameworkBundle\Controller\AbstractController; use Symfony\Component\HttpFoundation\JsonResponse; use Symfony\Component\Routing\Attribute\Route;
final class ApiController extends AbstractController { #[Route('/api/offers', name:'api_offers')] public function offers(EntityManagerInterface $em):JsonResponse { $rows=$em->createQueryBuilder()->select('o,p,s')->from(Offer::class,'o')->join('o.product','p')->join('o.store','s')->where('o.inStock = true AND o.checkedAt >= :since')->setParameter('since',new \DateTimeImmutable('-48 hours'))->orderBy('o.unitCost','ASC')->setMaxResults(1000)->getQuery()->getResult(); return $this->json(array_map(fn($o)=>['id'=>$o->getId(),'productId'=>$o->product->getId(),'displayCount'=>$o->displayCount,'unitCost'=>$o->unitCost,'shippingKnown'=>$o->shippingKnown,'currency'=>$o->currency,'game'=>$o->product->game,'set'=>$o->product->setCode,'name'=>$o->product->setName,'language'=>$o->product->language,'store'=>$o->store->name,'country'=>$o->store->country,'shippingOrigin'=>$o->shippingOrigin,'price'=>$o->price,'shipping'=>$o->shipping,'total'=>$o->landedCost,'url'=>$o->url,'checkedAt'=>$o->checkedAt->format(DATE_ATOM)],$rows)); } }
